@@ -1080,6 +1080,17 @@ impl Planes {
                         if let Err(error) = device.poll(wgpu::PollType::Poll) {
                             tracing::error!(%error, "GPU completion resource reclamation failed");
                         }
+                        if let Some(report) = device.generate_allocator_report() {
+                            let mut labels = std::collections::BTreeMap::new();
+                            for allocation in &report.allocations {
+                                let value = labels.entry(allocation.name.as_str()).or_insert((0_u64, 0_u64));
+                                value.0 += 1;
+                                value.1 += allocation.size;
+                            }
+                            tracing::debug!(allocated = report.total_allocated_bytes,
+                                reserved = report.total_reserved_bytes, labels = ?labels,
+                                "completed picture allocator census");
+                        }
                         completed.store(true, Ordering::Release);
                         if wake {
                             waker.wake();
